.workspace{flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 340px}.collection{min-width:0;overflow:auto;padding:20px 0 10px 32px}.collection-heading{display:flex;align-items:center;justify-content:space-between;min-height:32px;padding-right:32px;margin-bottom:20px}.collection-heading h1{display:flex;align-items:center;gap:16px;font:400 32px/1.1 Newsreader,Georgia,serif;letter-spacing:-.02em}.collection-heading h1>span{font:400 16px/1.4 'Library Inter',sans-serif;color:var(--app-muted)}.collection-heading button{min-height:48px;background:none;border:0;color:var(--app-accent);cursor:pointer}.book-grid{display:flex;gap:36px;overflow-x:auto;padding:8px 32px 12px 0;scroll-snap-type:x proximity;scrollbar-width:thin;scrollbar-color:#bac3b9 transparent}.book-choice{display:flex;flex-direction:column;align-items:start;gap:18px;flex:none;max-width:280px;min-width:0;padding:0;border:0;background:none;color:inherit;text-align:left;cursor:pointer;scroll-snap-align:start}.cover-space{display:flex;justify-content:center;align-items:end;height:clamp(270px,calc(100svh - 350px),440px);max-width:280px}.jacket{position:relative;display:flex;max-width:100%;max-height:100%;height:100%;box-shadow:1px 6px 10px #22291f20}.jacket img{display:block;height:100%;max-width:100%;width:auto;object-fit:contain;object-position:bottom;outline:1px solid #20262015;outline-offset:-1px}.is-selected .jacket{transform:translateY(-7px)}.is-selected .cover-space{border-bottom:3px solid var(--app-accent)}.book-choice:hover .jacket{box-shadow:2px 9px 14px #26382d2c}.missing-cover{height:100%;width:auto;aspect-ratio:2/3;max-width:100%;background:#e7e1d3;border:1px solid #d2cbbb;display:flex;flex-direction:column;justify-content:space-between;padding:32px 25px;text-align:left;font:400 40px/1.1 Newsreader,Georgia,serif;overflow-wrap:anywhere}.missing-cover small{font:400 16px/1.4 'Library Inter',system-ui,sans-serif;color:#455241}.book-subtitle{display:block;max-width:30ch;font-size:.8rem;line-height:1.4;color:var(--app-muted);overflow-wrap:anywhere}.caption{display:flex;flex-direction:column;gap:5px;max-width:100%}.book-title{font-size:19px;line-height:1.3;font-weight:600}.book-author{font-size:16px;color:var(--app-muted);line-height:1.35}.is-selected .book-title{color:var(--app-accent)}#no-results{padding:36px 0;color:var(--app-muted)}.empty-library{display:grid;gap:16px;padding:40px 0}.empty-library h2{font:400 36px/1.1 Newsreader,Georgia,serif}.empty-library a{min-height:48px;color:var(--app-accent)}
